export const GLOSSARY_SHARD = Object.freeze({"market-capitalization":{"slug":"market-capitalization","cat":"basics","en":"Market capitalization","contentLocale":"id","term":"Market capitalization (kapitalisasi pasar)","aka":["market cap","kapitalisasi pasar","mcap"],"short":"Market capitalization atau kapitalisasi pasar adalah nilai total sebuah aset kripto yang beredar, dihitung dari harga saat ini dikali jumlah suplai yang beredar.","body":[["Rumusnya sederhana: harga per koin x ",["circulating supply","circulating-supply"],". Angka ini membantu Anda membandingkan ukuran proyek. Harga per koin saja tidak berarti banyak, karena koin dengan harga 0,01 ",["USDT","usdt"]," bisa saja punya kapitalisasi lebih besar daripada koin seharga 50 USDT jika suplainya jauh lebih banyak."],"Kapitalisasi pasar sering dipakai untuk mengelompokkan koin menjadi large cap, mid cap, dan small cap. Koin small cap biasanya lebih volatil dan likuiditasnya lebih tipis. Peringkat di situs data seperti CoinGecko atau CoinMarketCap juga diurutkan berdasarkan angka ini.","Ingat bahwa market cap bukan jumlah uang yang benar-benar masuk ke proyek. Jika banyak koin dijual sekaligus, harga bisa turun jauh lebih cepat daripada yang tersirat dari angka kapitalisasi. Situs data juga bisa memakai angka suplai berbeda, jadi hasilnya kadang tidak sama."],"example":"Bandingkan dua koin. Koin A berharga 0,05 USDT dengan suplai beredar 20 miliar, sehingga market cap-nya 1 miliar USDT. Koin B berharga 25 USDT dengan suplai beredar 8 juta, sehingga market cap-nya 200 juta USDT. Meski harga per koin A jauh lebih murah, ukuran pasar A lima kali lebih besar daripada B. Agar A naik ke 0,50 USDT, market cap-nya harus menjadi 10 miliar USDT.","mistakes":["Menganggap koin berharga murah pasti bisa naik ke 1 dolar tanpa menghitung market cap yang dibutuhkan.","Menyamakan market cap dengan uang yang sudah diinvestasikan ke proyek.","Mengabaikan perbedaan market cap dan fully diluted valuation pada koin yang suplainya masih banyak terkunci."],"faq":[{"q":"Bagaimana cara menghitung market cap kripto?","a":"Kalikan harga saat ini dengan circulating supply. Misalnya harga 2 USDT dikali 500 juta koin beredar sama dengan market cap 1 miliar USDT."},{"q":"Apakah market cap besar berarti lebih aman?","a":"Koin dengan market cap besar biasanya lebih likuid dan tidak terlalu mudah digerakkan, tetapi harganya tetap bisa turun tajam. Market cap besar bukan jaminan keamanan."}],"title":"Apa itu market cap kripto? Arti kapitalisasi pasar","description":"Pelajari arti market cap atau kapitalisasi pasar kripto, cara menghitungnya, dan kenapa harga per koin saja bisa menyesatkan.","related":[["fully-diluted-valuation","Fully diluted valuation (FDV)","Fully diluted valuation (FDV) adalah perkiraan nilai sebuah proyek kripto jika seluruh suplai maksimal tokennya sudah beredar, dihitung dari harga saat ini dikali suplai maksimal atau total."],["circulating-supply","Circulating supply (suplai beredar)","Circulating supply adalah jumlah koin atau token yang saat ini benar-benar beredar dan bisa diperdagangkan di pasar, tidak termasuk yang masih terkunci atau belum diterbitkan."],["trading-volume","Volume trading (trading volume)","Volume trading adalah total nilai atau jumlah aset yang diperdagangkan dalam periode tertentu, misalnya 24 jam, dan dipakai untuk mengukur seberapa aktif sebuah pasar."],["tokenomics","Tokenomics","Tokenomics adalah desain ekonomi sebuah token, mencakup jumlah suplai, cara distribusi, jadwal unlock, kegunaan token, dan mekanisme yang menambah atau mengurangi suplai."],["altcoin","Altcoin","Altcoin adalah sebutan untuk semua aset kripto selain Bitcoin, mulai dari jaringan besar seperti Ethereum dan Solana hingga token kecil yang baru diluncurkan."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"market-maker":{"slug":"market-maker","cat":"trading","en":"Market maker","contentLocale":"id","term":"Market maker","aka":["MM","penyedia likuiditas","pembuat pasar"],"short":"Market maker adalah pihak yang terus-menerus memasang order beli dan jual di dekat harga pasar sehingga trader lain selalu punya lawan transaksi, dan ia mendapat keuntungan dari selisih spread.","body":[["Market maker biasanya adalah perusahaan trading profesional yang memakai algoritma. Mereka memasang bid sedikit di bawah harga dan ask sedikit di atas harga, lalu memperbarui order itu ribuan kali sehari. Karena order mereka menunggu di ",["order book","order-book"],", mereka termasuk maker dan sering mendapat tarif biaya khusus dari exchange."],["Peran mereka membuat spread tipis dan order book tebal, sehingga ",["slippage","slippage"]," Anda lebih kecil. Proyek token juga sering bekerja sama dengan market maker saat listing. Risikonya, ",["likuiditas","liquidity"]," ini bisa ditarik saat pasar bergejolak, sehingga pasar mendadak tipis tepat ketika Anda membutuhkannya."],["Di ",["DeFi","defi"],", peran market maker digantikan oleh ",["AMM","amm"]," dan liquidity provider yang menyetor dana ke pool. Siapa pun bisa menjadi penyedia likuiditas, dengan risiko seperti ",["impermanent loss","impermanent-loss"],"."]],"example":"Misalkan BTC diperdagangkan di sekitar 64.000 USDT. Market maker memasang bid di 63.995 dan ask di 64.005, masing-masing 0,5 BTC. Jika dalam satu menit ada penjual yang mengisi bid-nya dan pembeli yang mengisi ask-nya, ia membeli 0,5 BTC seharga 31.997,5 USDT dan menjual 0,5 BTC seharga 32.002,5 USDT. Laba kotornya 5 USDT sebelum biaya. Keuntungan kecil ini diulang ribuan kali, tetapi ia menanggung risiko jika harga bergerak tajam saat ia masih memegang persediaan.","mistakes":["Menganggap market maker selalu memanipulasi harga, padahal tugas utamanya menyediakan likuiditas.","Mengira likuiditas dari market maker selalu ada, padahal bisa hilang saat volatilitas tinggi.","Menyamakan market maker dengan whale; whale memegang posisi besar, market maker berputar dalam posisi kecil yang seimbang."],"faq":[{"q":"Bagaimana market maker menghasilkan uang?","a":"Terutama dari spread antara harga beli dan jual yang mereka pasang, ditambah rebate atau biaya maker yang rendah dari exchange. Mereka berusaha menjaga posisi tetap netral."},{"q":"Apakah saya bisa menjadi market maker?","a":"Secara teknis setiap limit order yang menunggu di order book adalah order maker. Namun market making profesional butuh modal, algoritma, dan manajemen risiko yang serius."}],"title":"Apa itu market maker di kripto? Peran dan cara kerjanya","description":"Pelajari apa itu market maker, bagaimana mereka menjaga spread tetap tipis, cara mereka mendapat untung, dan risikonya bagi trader.","related":[["liquidity","Likuiditas (liquidity)","Likuiditas adalah seberapa mudah dan cepat sebuah aset kripto bisa dibeli atau dijual dalam jumlah besar tanpa menggeser harganya secara signifikan."],["bid-ask-spread","Bid-ask spread (spread)","Bid-ask spread adalah selisih antara harga beli tertinggi (bid) dan harga jual terendah (ask) di order book pada satu waktu."],["maker-taker-fees","Biaya maker dan taker (maker-taker fee)","Biaya maker dan taker adalah dua tarif biaya trading di exchange: maker dikenakan pada order yang menambah likuiditas ke order book, sedangkan taker dikenakan pada order yang langsung mengambil likuiditas yang sudah ada."],["order-book","Order book (buku order)","Order book adalah daftar real-time semua order beli dan order jual yang menunggu di sebuah pasangan perdagangan, disusun berdasarkan harga dan jumlahnya."],["amm","AMM (automated market maker)","AMM adalah mekanisme di DEX yang menentukan harga secara otomatis berdasarkan rumus dan isi liquidity pool, sehingga Anda bisa swap tanpa menunggu pembeli atau penjual lain."]],"lesson":null,"coin":null,"tool":null,"cta":false},"risk-reward-ratio":{"slug":"risk-reward-ratio","cat":"trading","en":"Risk-reward ratio","contentLocale":"id","term":"Rasio risk-reward (risk-reward ratio)","aka":["risk reward","RR","R:R","rasio risiko-imbal hasil"],"short":"Rasio risk-reward adalah perbandingan antara potensi kerugian sebuah trade (jarak ke stop loss) dan potensi keuntungannya (jarak ke take profit), misalnya 1:2.","body":["Rasio ini membantu Anda menilai apakah sebuah trade layak diambil sebelum masuk. Rasio 1:3 berarti untuk setiap 1 unit risiko, target keuntungannya 3 unit. Semakin besar rasionya, semakin rendah win rate yang Anda butuhkan untuk tetap untung dalam jangka panjang.",["Win rate impas bisa dihitung dengan rumus 1 dibagi (1 + R). Dengan rasio 1:2, Anda impas jika menang sekitar 33% dari trade; dengan 1:1, Anda butuh 50%. Ini belum termasuk ",["biaya trading","maker-taker-fees"]," dan ",["slippage","slippage"],", yang menggeser titik impas sedikit lebih tinggi."],["Rasio tinggi tidak otomatis lebih baik. Target yang terlalu jauh lebih jarang tercapai. Yang penting adalah target dan ",["stop loss","stop-loss"]," ditentukan dari struktur pasar seperti ",["support dan resistance","support-and-resistance"],", bukan dari angka yang diinginkan."]],"example":["Anda berencana long LINK di 15,00 ",["USDT","usdt"]," dengan stop loss di 14,40 dan ",["take profit","take-profit"]," di 16,80. Risikonya 0,60 USDT per koin, potensi untungnya 1,80 USDT per koin, jadi rasionya 1:3. Jika Anda mengambil 10 trade serupa dengan ukuran risiko 30 USDT per trade dan hanya menang 3 kali, hasilnya 3 x 90 = 270 USDT untung dikurangi 7 x 30 = 210 USDT rugi, bersih 60 USDT sebelum biaya."],"mistakes":["Menggeser stop loss lebih jauh saat harga mendekat, sehingga rasio yang direncanakan rusak.","Memasang target yang tidak realistis hanya demi rasio besar di atas kertas.","Menghitung rasio tanpa memasukkan biaya trading dan funding pada posisi futures."],"faq":[{"q":"Berapa rasio risk-reward yang bagus?","a":"Banyak trader mencari minimal 1:2, tetapi rasio yang baik tergantung win rate strategi Anda. Strategi dengan win rate tinggi bisa tetap untung dengan rasio 1:1."},{"q":"Apa hubungan rasio risk-reward dan win rate?","a":"Keduanya harus dilihat bersama. Win rate impas sama dengan 1 dibagi (1 + R), jadi rasio 1:3 butuh win rate sekitar 25% untuk impas sebelum biaya."}],"title":"Apa itu rasio risk-reward? Arti dan cara menghitungnya","description":"Pahami rasio risk-reward dalam trading kripto, cara menghitungnya, dan hubungannya dengan win rate agar strategi Anda tetap untung.","related":[["position-sizing","Position sizing (ukuran posisi)","Position sizing adalah cara menentukan berapa besar modal yang dipakai untuk satu trade, berdasarkan seberapa banyak kerugian yang siap Anda tanggung jika stop loss tersentuh."],["stop-loss","Stop loss","Stop loss adalah order otomatis untuk menutup posisi ketika harga bergerak melawan Anda sampai level tertentu, agar kerugian dibatasi sesuai rencana."],["take-profit","Take profit","Take profit adalah order otomatis untuk menutup posisi ketika harga mencapai target keuntungan yang sudah Anda tetapkan."],["oco-order","OCO order (one cancels the other)","OCO order adalah pasangan dua order, biasanya take profit dan stop loss, di mana ketika salah satunya tereksekusi, order lainnya otomatis dibatalkan."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Tentukan berapa banyak kerugian sebelum memutuskan berapa banyak yang dibeli"},"coin":null,"tool":null,"cta":false},"futures-contract":{"slug":"futures-contract","cat":"derivatives","en":"Futures contract","contentLocale":"id","term":"Kontrak futures (kontrak berjangka)","aka":["futures","kontrak berjangka","futures kripto"],"short":"Kontrak futures adalah perjanjian untuk membeli atau menjual aset pada harga yang disepakati, sehingga Anda bisa mengambil posisi naik (long) atau turun (short) tanpa harus memegang asetnya langsung.","body":[["Di exchange kripto, futures diperdagangkan dengan margin. Anda hanya menyetor sebagian nilai posisi sebagai jaminan, lalu untung atau rugi dihitung dari selisih harga. Karena itu futures memungkinkan ",["leverage","leverage"],", sekaligus membawa risiko ",["likuidasi","liquidation"]," jika kerugian menghabiskan margin."],["Ada dua jenis utama. ",["Futures berjangka","delivery-futures"]," atau delivery futures punya tanggal jatuh tempo, misalnya kuartalan, dan diselesaikan pada tanggal itu. ",["Perpetual futures","perpetual-futures"]," tidak punya jatuh tempo dan memakai ",["funding rate","funding-rate"]," agar harganya tetap dekat dengan harga spot. Di kripto, sebagian besar volume futures ada di kontrak perpetual."],["Kontrak juga dibedakan dari jaminannya: ",["USDT","usdt"],"-margined (linear) atau coin-margined (inverse). Spesifikasi seperti ukuran kontrak, leverage maksimal, dan jam settlement berbeda tiap exchange, jadi baca halaman spesifikasi kontrak sebelum trading. Di Indonesia, pengawasan aset kripto berpindah dari Bappebti ke OJK sejak Januari 2025, dan ketersediaan produk derivatif mengikuti aturan yang berlaku."]],"example":"Misalkan Anda yakin harga ETH akan turun dari 3.000 USDT dan membuka short senilai 3.000 USDT, setara 1 ETH, dengan margin 600 USDT (leverage 5x). Jika ETH turun ke 2.700, keuntungan Anda 300 USDT, atau 50% dari margin, sebelum biaya. Jika ETH justru naik ke 3.300, Anda rugi 300 USDT, setengah margin Anda hilang, dan posisi makin dekat ke harga likuidasi.","mistakes":["Membuka futures tanpa memahami bahwa kerugian dihitung dari nilai posisi, bukan dari margin.","Tidak membedakan kontrak perpetual dan kontrak berjangka yang punya tanggal jatuh tempo.","Memakai leverage maksimal karena tersedia di aplikasi, bukan karena sesuai rencana risiko."],"faq":[{"q":"Apa beda futures dan spot?","a":"Di spot, Anda membeli dan memiliki koinnya. Di futures, Anda memegang kontrak yang nilainya mengikuti harga koin, bisa long atau short, dan biasanya memakai margin serta leverage."},{"q":"Apakah futures cocok untuk pemula?","a":"Futures bisa dipakai pemula dengan leverage rendah dan ukuran kecil, tetapi Anda perlu paham margin, likuidasi, dan funding rate terlebih dahulu. Tanpa itu, kerugian bisa datang sangat cepat."}],"title":"Apa itu futures kripto? Arti kontrak berjangka","description":"Pelajari apa itu kontrak futures kripto, beda perpetual dan berjangka, cara kerja margin, long, short, dan risiko likuidasi.","related":[["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."],["delivery-futures","Futures berjangka (delivery futures)","Futures berjangka atau delivery futures adalah kontrak futures dengan tanggal jatuh tempo tetap, misalnya mingguan atau kuartalan, yang diselesaikan pada harga settlement di tanggal tersebut."],["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT."],["margin-trading","Margin trading","Margin trading adalah cara trading dengan meminjam dana dari exchange menggunakan aset Anda sebagai jaminan, sehingga Anda bisa membuka posisi lebih besar dari saldo sendiri atau menjual aset yang dipinjam."],["hedging","Hedging (lindung nilai)","Hedging adalah strategi membuka posisi yang berlawanan dengan aset atau posisi yang Anda pegang untuk mengurangi risiko kerugian akibat pergerakan harga, dengan konsekuensi potensi untungnya ikut berkurang."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: Anda tidak membeli hal yang sama"},"coin":null,"tool":"/topics/derivatives","cta":true},"cross-margin":{"slug":"cross-margin","cat":"derivatives","en":"Cross margin","contentLocale":"id","term":"Margin silang (cross margin)","aka":["cross margin","margin cross","mode cross"],"short":"Margin silang adalah mode margin di mana seluruh saldo yang tersedia di akun futures dipakai bersama sebagai jaminan untuk semua posisi terbuka, sehingga posisi lebih sulit dilikuidasi tetapi seluruh saldo ikut dipertaruhkan.","body":[["Dalam mode cross, saldo bebas Anda otomatis menopang posisi yang sedang rugi. Keuntungan belum terealisasi dari satu posisi juga bisa membantu menahan posisi lain. Akibatnya, ",["harga likuidasi","liquidation-price"]," lebih jauh dibanding ",["isolated margin","isolated-margin"]," dengan margin yang sama."],"Kelemahannya, satu posisi yang rugi besar bisa menghabiskan seluruh saldo akun futures, termasuk dana yang sebenarnya Anda siapkan untuk trade lain. Harga likuidasi juga terus berubah saat Anda membuka posisi baru, menarik dana, atau saat posisi lain naik-turun.",["Cross margin sering dipakai trader yang menjalankan beberapa posisi yang saling berkaitan, misalnya ",["hedging","hedging"],", atau yang ingin menghindari ",["likuidasi","liquidation"]," akibat lonjakan harga singkat. Beberapa exchange juga menyediakan ",["akun terpadu","unified-trading-account"]," (unified account) yang memperluas konsep cross ke banyak produk sekaligus."]],"example":["Akun futures Anda berisi 4.000 ",["USDT","usdt"],". Anda membuka long BTC senilai 10.000 USDT dengan leverage 10x dalam mode cross. Margin awal yang dikunci hanya 1.000 USDT, tetapi seluruh 4.000 USDT bisa menahan posisi. Posisi baru dilikuidasi jika kerugian mendekati sekitar 3.950 USDT, setelah memperhitungkan maintenance margin sekitar 50 USDT, yaitu saat BTC turun sekitar 39,5%. Di isolated dengan margin 1.000 USDT, likuidasi sudah terjadi saat harga turun sekitar 9,5%."],"mistakes":["Membiarkan saldo besar di akun futures mode cross tanpa stop loss, sehingga satu kesalahan bisa menghabiskan semuanya.","Mengira leverage 10x di mode cross sama berisikonya dengan 10x di isolated.","Lupa bahwa menarik dana dari akun futures akan mendekatkan harga likuidasi posisi cross."],"faq":[{"q":"Apakah cross margin lebih aman daripada isolated?","a":"Cross membuat posisi lebih tahan terhadap pergerakan sementara, tetapi kerugian maksimalnya adalah seluruh saldo akun futures. Aman tidaknya tergantung disiplin stop loss Anda."},{"q":"Kenapa harga likuidasi di mode cross berubah-ubah?","a":"Karena jaminannya adalah seluruh saldo, sehingga setiap perubahan saldo, posisi lain, atau PnL belum terealisasi menggeser titik likuidasi."}],"title":"Apa itu cross margin? Arti margin silang di futures kripto","description":"Pahami cross margin atau margin silang: cara saldo akun menopang posisi, kelebihan, risiko kehilangan seluruh saldo, dan beda dengan isolated.","related":[["isolated-margin","Margin terisolasi (isolated margin)","Margin terisolasi adalah mode margin di mana setiap posisi punya jaminan sendiri yang terpisah, sehingga jika posisi itu dilikuidasi, kerugiannya hanya terbatas pada margin yang dialokasikan ke posisi tersebut."],["portfolio-margin","Portfolio margin","Portfolio margin adalah mode margin yang menghitung kebutuhan jaminan berdasarkan risiko gabungan seluruh portofolio, sehingga posisi yang saling mengimbangi bisa membutuhkan margin jauh lebih kecil."],["unified-trading-account","Akun trading terpadu (Unified Trading Account)","Akun trading terpadu adalah jenis akun bursa yang menggabungkan saldo spot, margin, futures, dan opsi dalam satu dompet, sehingga satu pool aset bisa dipakai sebagai margin untuk berbagai produk."],["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang."]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"Margin silang: mengapa satu kerugian bisa memukul posisi Anda lainnya"},"coin":null,"tool":null,"cta":false},"long-and-short":{"slug":"long-and-short","cat":"derivatives","en":"Long and short positions","contentLocale":"id","term":"Posisi long dan short","aka":["long","short","buka long","buka short"],"short":"Posisi long adalah posisi yang untung saat harga naik, sedangkan posisi short adalah posisi yang untung saat harga turun; keduanya bisa dibuka di futures maupun margin trading.","body":[["Long berarti Anda membeli dengan harapan menjual lebih mahal nanti. Membeli koin di spot pada dasarnya juga posisi long. Short berarti Anda menjual lebih dulu dengan harapan membeli kembali lebih murah. Di futures, Anda bisa membuka short tanpa memiliki koinnya; di ",["margin trading","margin-trading"],", Anda meminjam koin untuk dijual."],["Risiko keduanya tidak simetris. Kerugian long terbatas karena harga paling rendah nol. Kerugian short secara teori tidak terbatas karena harga bisa terus naik, meskipun di exchange kripto kerugian akun futures dibatasi oleh ",["likuidasi","liquidation"],"."],["Di ",["perpetual futures","perpetual-futures"],", posisi long dan short juga saling membayar ",["funding rate","funding-rate"],". Beberapa exchange mendukung hedge mode, yaitu memegang long dan short di pasangan yang sama secara bersamaan, sedangkan mode one-way hanya memungkinkan satu arah posisi bersih."]],"example":["Dua trader memakai kontrak ",["USDT","usdt"],"-margined BNB di harga 580 USDT. Trader A membuka long 5 BNB, trader B membuka short 5 BNB. Jika BNB naik ke 609, naik 5%, A untung 5 x 29 = 145 USDT dan B rugi 145 USDT. Jika BNB turun ke 551, turun 5%, hasilnya berbalik: B untung 145 USDT dan A rugi 145 USDT, sebelum biaya dan funding."],"mistakes":["Membuka short hanya karena harga sudah naik banyak, tanpa alasan dan stop loss yang jelas.","Tidak sadar bahwa menekan tombol jual di futures saat tidak memegang posisi akan membuka short baru.","Mengabaikan funding rate yang bisa membuat salah satu sisi membayar biaya terus-menerus."],"faq":[{"q":"Apa arti long dan short di kripto?","a":"Long berarti bertaruh harga naik, short berarti bertaruh harga turun. Di futures, keduanya bisa dibuka dengan mudah menggunakan margin."},{"q":"Apakah saya bisa short di pasar spot?","a":"Tidak secara langsung. Di spot Anda hanya bisa menjual koin yang Anda miliki. Untuk short, Anda perlu futures atau margin trading yang meminjamkan koin."}],"title":"Apa itu long dan short di trading kripto?","description":"Pahami arti posisi long dan short di kripto, cara keduanya untung dan rugi, perbedaan risikonya, serta hedge mode di futures.","related":[["short-selling","Short selling (jual short)","Short selling adalah strategi mendapat untung dari penurunan harga dengan menjual aset lebih dulu, lalu membelinya kembali di harga lebih rendah untuk menutup posisi."],["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."],["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT."],["long-short-ratio","Rasio long/short (long/short ratio)","Rasio long/short adalah perbandingan antara jumlah akun atau nilai posisi long dan short di pasar futures, dipakai untuk membaca sentimen trader terhadap sebuah aset."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: Anda tidak membeli hal yang sama"},"coin":null,"tool":null,"cta":true},"short-selling":{"slug":"short-selling","cat":"derivatives","en":"Short selling","contentLocale":"id","term":"Short selling (jual short)","aka":["shorting","short","jual kosong"],"short":"Short selling adalah strategi mendapat untung dari penurunan harga dengan menjual aset lebih dulu, lalu membelinya kembali di harga lebih rendah untuk menutup posisi.","body":[["Di pasar tradisional, short selling dilakukan dengan meminjam saham lalu menjualnya. Di kripto, ada dua cara umum: ",["margin trading","margin-trading"],", di mana Anda meminjam koin dan membayar bunga, serta futures, di mana Anda cukup membuka posisi short pada kontrak tanpa meminjam aset."],["Short selling dipakai untuk spekulasi saat Anda memperkirakan harga turun, dan untuk ",["lindung nilai","hedging"],", misalnya melindungi nilai koin yang Anda pegang. Pemegang ",["ETH","ethereum"]," jangka panjang bisa membuka short ETH di futures agar nilai portofolionya tidak ikut turun dalam periode tertentu."],["Risikonya khas: kerugian bertambah ketika harga naik, dan kenaikan bisa sangat cepat saat banyak short terpaksa menutup posisi, yaitu ",["short squeeze","short-squeeze"],". Biaya juga perlu dihitung, baik bunga pinjaman di margin maupun ",["funding rate","funding-rate"]," di ",["perpetual","perpetual-futures"],"."]],"example":"Anda short 1.000 ADA di futures pada harga 0,50 USDT, nilai posisi 500 USDT, dengan leverage 2x sehingga margin 250 USDT. Harga turun ke 0,42 dan Anda menutup posisi dengan membeli kembali 1.000 ADA seharga 420 USDT. Keuntungan Anda 80 USDT, atau 32% dari margin, sebelum biaya dan funding. Jika harga justru naik ke 0,60, Anda rugi 100 USDT atau 40% dari margin.","mistakes":["Melawan tren naik yang kuat hanya karena merasa harga sudah terlalu tinggi.","Short koin dengan likuiditas tipis yang mudah dipompa dan memicu short squeeze.","Tidak menghitung funding negatif yang membuat pihak short harus membayar long."],"faq":[{"q":"Bagaimana cara short kripto?","a":"Cara paling umum adalah membuka posisi short di kontrak futures atau perpetual. Alternatifnya, pakai margin trading dengan meminjam koin dan menjualnya."},{"q":"Berapa kerugian maksimal saat short?","a":"Secara teori tidak terbatas karena harga bisa terus naik. Dalam praktik di exchange kripto, kerugian dibatasi oleh likuidasi margin Anda, tetapi itu tetap bisa berarti kehilangan seluruh margin."}],"title":"Apa itu short selling kripto? Cara kerja dan risikonya","description":"Pelajari short selling di kripto: cara short lewat futures atau margin, contoh hitungan untung-rugi, kegunaan hedging, dan risikonya.","related":[["long-and-short","Posisi long dan short","Posisi long adalah posisi yang untung saat harga naik, sedangkan posisi short adalah posisi yang untung saat harga turun; keduanya bisa dibuka di futures maupun margin trading."],["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."],["margin-trading","Margin trading","Margin trading adalah cara trading dengan meminjam dana dari exchange menggunakan aset Anda sebagai jaminan, sehingga Anda bisa membuka posisi lebih besar dari saldo sendiri atau menjual aset yang dipinjam."],["short-squeeze","Short squeeze","Short squeeze adalah kenaikan harga yang cepat dan tajam karena banyak trader short terpaksa menutup posisi dengan membeli kembali aset, baik karena stop loss maupun likuidasi, sehingga mendorong harga naik lebih jauh."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: Anda tidak membeli hal yang sama"},"coin":null,"tool":null,"cta":false},"futures-basis":{"slug":"futures-basis","cat":"derivatives","en":"Futures basis","contentLocale":"id","term":"Basis futures (futures basis)","aka":["basis","premium futures","basis spread"],"short":"Basis futures adalah selisih antara harga kontrak futures dan harga spot aset yang sama, biasanya dinyatakan dalam persen atau persen per tahun.","body":[["Jika harga futures di atas spot, basisnya positif dan pasar disebut contango. Ini kondisi paling umum di kripto saat sentimen positif, karena banyak trader rela membayar lebih untuk eksposur ",["leverage","leverage"],". Jika harga futures di bawah spot, basisnya negatif atau backwardation, yang sering muncul saat pasar tertekan."],["Untuk ",["futures berjangka","delivery-futures"],", basis menyempit menuju nol seiring mendekati jatuh tempo, karena pada settlement harga futures harus bertemu ",["harga indeks","index-price"],". Untuk membandingkan kontrak dengan jatuh tempo berbeda, trader mengubah basis menjadi angka tahunan: basis persen dikali 365 dibagi sisa hari."],["Di ",["perpetual","perpetual-futures"],", basis dijaga tetap kecil oleh ",["funding rate","funding-rate"],". Basis tinggi menjadi sinyal leverage long yang ramai, dan juga peluang bagi strategi cash-and-carry: membeli spot dan short futures untuk mengunci selisihnya."]],"example":["Misalkan ",["ETH","ethereum"]," spot di 2.500 USDT dan futures yang jatuh tempo 60 hari lagi di 2.540 USDT. Basisnya 40 USDT atau 1,6%. Disetahunkan, 1,6% x 365 dibagi 60 = sekitar 9,7% per tahun. Seorang trader membeli 10 ETH spot seharga 25.000 USDT dan short 10 ETH futures di 2.540. Pada jatuh tempo, keduanya bertemu, sehingga ia mengunci sekitar 400 USDT sebelum biaya, berapa pun harga ETH saat itu."],"mistakes":["Membandingkan basis persen dari kontrak dengan jatuh tempo berbeda tanpa menyetahunkannya.","Menganggap basis positif sebagai prediksi bahwa harga spot akan naik.","Mengabaikan kebutuhan margin pada posisi short futures saat harga naik tajam sebelum jatuh tempo."],"faq":[{"q":"Apa itu contango dan backwardation?","a":"Contango adalah kondisi ketika harga futures di atas spot, dan backwardation ketika futures di bawah spot. Di kripto, contango lebih sering terjadi saat pasar optimis."},{"q":"Bagaimana cara menghitung basis tahunan?","a":"Hitung basis dalam persen, lalu kalikan dengan 365 dan bagi dengan sisa hari sampai jatuh tempo. Ini memudahkan perbandingan antar-kontrak dan dengan funding rate."}],"title":"Apa itu basis futures? Arti contango dan backwardation","description":"Pahami basis futures di kripto: selisih harga futures dan spot, cara menyetahunkannya, contango, backwardation, dan strategi cash-and-carry.","related":[["delivery-futures","Futures berjangka (delivery futures)","Futures berjangka atau delivery futures adalah kontrak futures dengan tanggal jatuh tempo tetap, misalnya mingguan atau kuartalan, yang diselesaikan pada harga settlement di tanggal tersebut."],["funding-rate","Funding rate","Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot."],["index-price","Harga indeks (index price)","Harga indeks adalah rata-rata tertimbang harga spot sebuah aset dari beberapa exchange besar, dipakai exchange sebagai acuan untuk mark price, funding rate, dan settlement kontrak futures."],["funding-rate-arbitrage","Arbitrase funding rate (funding rate arbitrage)","Arbitrase funding rate adalah strategi netral pasar yang membeli aset di spot dan membuka short dengan ukuran sama di perpetual, sehingga risiko harga saling meniadakan dan keuntungan berasal dari pembayaran funding."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"blockchain-network":{"slug":"blockchain-network","cat":"wallets-security","en":"Deposit network (chain selection)","contentLocale":"id","term":"Jaringan deposit (pilihan chain)","aka":["pilihan jaringan","network deposit","chain","jaringan blockchain"],"short":"Jaringan deposit adalah blockchain yang Anda pilih untuk mengirim atau menerima sebuah aset, misalnya USDT lewat Tron, Ethereum, atau BNB Smart Chain, dan pilihan ini harus sama di sisi pengirim dan penerima.","body":[["Banyak token tersedia di lebih dari satu ",["blockchain","blockchain"],". ",["USDT","usdt"]," misalnya diterbitkan di ",["Ethereum","ethereum"]," (ERC20), Tron (TRC20), dan beberapa jaringan lain. Token-token itu bernilai sama, tetapi berada di buku besar yang berbeda, sehingga tidak otomatis berpindah dari satu jaringan ke jaringan lain."],["Saat menarik dari exchange, Anda akan diminta memilih jaringan. Jaringan itu menentukan ",["biaya penarikan","withdrawal-fee"],", kecepatan ",["konfirmasi","block-confirmations"],", dan format alamat. Exchange tujuan atau dompet penerima harus mendukung jaringan yang sama. Jika tidak, dana bisa tertahan, dan pemulihannya bergantung pada kebijakan masing-masing platform, kadang dikenai biaya, kadang tidak bisa sama sekali."],["Biaya dan kecepatan sangat berbeda antar jaringan. Ethereum mainnet umumnya lebih mahal saat ramai, sedangkan Tron, BNB Smart Chain, atau ",["layer 2","layer-2"]," sering lebih murah. Periksa halaman deposit exchange tujuan untuk melihat jaringan apa saja yang didukung sebelum menarik."]],"example":"Misalnya Anda ingin memindahkan 1.000 USDT dari exchange A ke exchange B. Exchange A menawarkan ERC20 dengan biaya penarikan contoh 5 USDT dan TRC20 dengan biaya contoh 1 USDT. Halaman deposit exchange B menampilkan alamat untuk TRC20. Anda memilih TRC20, sehingga yang tiba 999 USDT. Jika Anda memilih ERC20 padahal alamat yang disalin hanya untuk TRC20, formulir biasanya menolak karena format alamat berbeda.","mistakes":["Memilih jaringan termurah tanpa memastikan exchange atau dompet tujuan mendukung jaringan tersebut.","Mengira alamat 0x yang sama otomatis menerima token dari semua jaringan EVM di satu saldo.","Mengabaikan peringatan jaringan di halaman deposit karena terburu-buru."],"faq":[{"q":"Apa yang terjadi jika saya salah memilih jaringan?","a":"Dana bisa tidak muncul di saldo tujuan. Beberapa exchange bisa memulihkannya lewat tiket dukungan, kadang dengan biaya, tetapi ada juga kasus yang tidak bisa dipulihkan."},{"q":"Jaringan mana yang paling murah untuk USDT?","a":"Biaya berubah sesuai kondisi jaringan dan kebijakan exchange. Bandingkan biaya penarikan di halaman penarikan dan pastikan jaringan itu didukung di sisi penerima."}],"title":"Apa itu jaringan deposit? Cara memilih chain yang benar","description":"Pelajari arti jaringan deposit, beda ERC20, TRC20, dan BEP20, serta cara memilih chain yang benar saat transfer kripto.","related":[["wallet-address","Alamat dompet (wallet address)","Alamat dompet adalah deretan karakter unik yang berfungsi seperti nomor rekening untuk menerima kripto di jaringan blockchain tertentu."],["memo-tag","Memo / destination tag","Memo atau destination tag adalah kode tambahan selain alamat yang dipakai beberapa jaringan, seperti XRP, Stellar, TON, atau Cosmos, untuk menandai akun penerima di dalam satu alamat bersama milik exchange."],["gas-fee","Gas fee (biaya gas)","Gas fee atau biaya gas adalah biaya yang Anda bayar kepada jaringan blockchain untuk memproses transaksi atau menjalankan smart contract, biasanya dalam coin asli jaringan tersebut."],["withdrawal-fee","Biaya penarikan (withdrawal fee)","Biaya penarikan adalah biaya yang dipotong bursa saat Anda menarik kripto ke alamat lain atau menarik rupiah ke rekening bank, biasanya berupa jumlah tetap per transaksi yang bergantung pada koin dan jaringan."],["transaction-hash","Transaction hash (TxID)","Transaction hash atau TxID adalah kode unik untuk setiap transaksi di blockchain, yang bisa Anda pakai untuk melacak status transfer di block explorer."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Sebelum transfer: jangan tebak-tebak hal-hal ini"},"coin":null,"tool":null,"cta":false},"mempool":{"slug":"mempool","cat":"onchain","en":"Mempool","contentLocale":"id","term":"Mempool","aka":["memory pool","antrean transaksi"],"short":"Mempool adalah ruang tunggu tempat transaksi yang sudah disiarkan tetapi belum masuk blok disimpan sementara oleh node, sebelum dipilih oleh penambang atau validator.","body":[["Saat Anda mengirim kripto, transaksi tidak langsung tercatat di ",["blockchain","blockchain"],". Transaksi lebih dulu disebarkan ke jaringan dan masuk mempool. Penambang atau ",["validator","validator"]," lalu memilih transaksi dari mempool untuk dimasukkan ke blok berikutnya, biasanya mendahulukan yang membayar biaya lebih tinggi."],["Ketika jaringan ramai, mempool menumpuk dan biaya naik. Di ",["Bitcoin","bitcoin"],", transaksi dengan biaya per byte rendah bisa tertahan berjam-jam, bahkan berhari-hari. Di ",["Ethereum","ethereum"],", ",["biaya gas","gas-fee"]," juga naik saat antrean panjang. Setiap ",["node","node"]," punya mempool sendiri, jadi isinya tidak selalu identik di seluruh jaringan."],"Mempool juga menjadi arena MEV. Karena transaksi terlihat sebelum dikonfirmasi, bot bisa mencoba mendahului atau mengapit transaksi swap besar di DEX. Itu sebabnya trader DEX memakai batas slippage dan sebagian memakai RPC privat."],"example":"Misalkan Anda mengirim 0,02 BTC dengan biaya 5 sat/vB, sementara transaksi lain di mempool membayar rata-rata 30 sat/vB. Transaksi Anda berukuran sekitar 140 vB, jadi biaya Anda 700 satoshi. Penambang mendahulukan transaksi yang lebih menguntungkan, sehingga transaksi Anda bisa tertunda lama. Jika dompet Anda mendukung Replace-By-Fee, Anda bisa menaikkan biaya ke 30 sat/vB, yaitu sekitar 4.200 satoshi, agar transaksi lebih cepat masuk blok.","mistakes":["Mengirim ulang transaksi yang sama saat yang pertama masih tertahan di mempool.","Memilih biaya terendah saat jaringan sedang padat lalu panik karena transfer tidak kunjung masuk.","Mengira transaksi di mempool sudah final, padahal belum punya satu konfirmasi pun."],"faq":[{"q":"Kenapa transaksi saya tertahan di mempool?","a":"Biasanya karena biaya yang Anda bayar lebih rendah daripada transaksi lain saat jaringan ramai. Anda bisa menunggu, menaikkan biaya jika dompet mendukung, atau menunggu transaksi kedaluwarsa dari mempool."},{"q":"Apakah transaksi bisa hilang dari mempool?","a":"Bisa. Node dapat membuang transaksi yang terlalu lama atau biayanya terlalu rendah, sehingga dana tetap di alamat pengirim dan Anda bisa mengirim ulang dengan biaya yang wajar."}],"title":"Apa itu mempool? Antrean transaksi blockchain","description":"Pahami mempool: kenapa transaksi tertahan, bagaimana biaya menentukan antrean, dan hubungannya dengan MEV.","related":[["gas-fee","Gas fee (biaya gas)","Gas fee atau biaya gas adalah biaya yang Anda bayar kepada jaringan blockchain untuk memproses transaksi atau menjalankan smart contract, biasanya dalam coin asli jaringan tersebut."],["transaction-hash","Transaction hash (TxID)","Transaction hash atau TxID adalah kode unik untuk setiap transaksi di blockchain, yang bisa Anda pakai untuk melacak status transfer di block explorer."],["mev","MEV (maximal extractable value)","MEV adalah keuntungan tambahan yang bisa diambil oleh pihak yang mengatur urutan transaksi dalam sebuah blok, misalnya dengan mendahului atau mengapit transaksi pengguna lain."],["block-confirmations","Konfirmasi blok (block confirmations)","Konfirmasi blok adalah jumlah blok yang sudah ditambahkan sejak transaksi Anda masuk ke blockchain, dan semakin banyak konfirmasi berarti semakin kecil kemungkinan transaksi itu dibatalkan."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Tertulis terkirim, tapi belum sampai. Harus cek ke mana?"},"coin":null,"tool":null,"cta":false},"no-kyc-exchange":{"slug":"no-kyc-exchange","cat":"regulation","en":"No-KYC exchange","contentLocale":"id","term":"Bursa tanpa KYC (no-KYC exchange)","aka":["no-KYC exchange","exchange tanpa KYC","bursa tanpa verifikasi"],"short":"Bursa tanpa KYC adalah platform yang mengizinkan Anda berdagang atau menarik kripto tanpa verifikasi identitas, biasanya dengan batas penarikan tertentu atau sebagai bursa terdesentralisasi.","body":[["Ada dua jenis. Pertama, ",["bursa terdesentralisasi","dex"]," (DEX) seperti Uniswap atau ",["perp DEX","perp-dex"]," on-chain, di mana Anda berdagang langsung dari dompet sendiri. Kedua, bursa terpusat yang membolehkan akun tanpa verifikasi dengan batas penarikan kecil. Kebijakan bursa terpusat bisa berubah sewaktu-waktu karena tekanan regulasi."],["Daya tariknya adalah privasi dan kemudahan. Namun risikonya nyata. Bursa terpusat tanpa ",["KYC","kyc"]," sering beroperasi tanpa izin di negara Anda, sehingga jika dana dibekukan atau platform tutup, Anda hampir tidak punya jalur hukum. Bursa juga bisa tiba-tiba mewajibkan KYC saat Anda ingin menarik dana."],["Di DEX, Anda memegang kunci sendiri, tetapi menanggung risiko ",["smart contract","smart-contract"],", ",["situs palsu","phishing"],", dan kesalahan transaksi. Selain itu, menghindari KYC tidak menghapus kewajiban pajak atau aturan di negara Anda."]],"example":["Misalkan Anda menyetor 4.000 ",["USDT","usdt"]," ke bursa terpusat yang mengizinkan penarikan tanpa KYC hingga setara 1.000 USDT per hari. Anda berdagang dan saldo menjadi 4.400 USDT. Saat ingin menarik semuanya, Anda butuh lima hari: empat hari masing-masing 1.000 dan satu hari 400. Lalu di hari kedua bursa mengumumkan semua akun wajib KYC sebelum penarikan berikutnya. Sisa 3.400 USDT kini terkunci sampai Anda menyerahkan identitas ke platform yang sebelumnya Anda pilih justru karena tidak meminta identitas."],"mistakes":["Menyimpan saldo besar di bursa tanpa izin hanya demi menghindari verifikasi.","Mengira tanpa KYC berarti transaksi tidak bisa dilacak sama sekali.","Lupa bahwa kebijakan tanpa KYC bisa dicabut kapan saja oleh bursa."],"faq":[{"q":"Apakah bursa tanpa KYC legal?","a":"Tergantung negara dan jenis platformnya. Banyak regulator, termasuk di Indonesia, mewajibkan penyedia jasa kripto yang melayani warganya untuk berizin dan menjalankan KYC."},{"q":"Apakah DEX termasuk bursa tanpa KYC?","a":"Umumnya ya, karena Anda berdagang langsung dari dompet tanpa akun. Namun antarmuka DEX bisa memblokir wilayah atau alamat tertentu, dan Anda menanggung sendiri risiko keamanan dompet."}],"title":"Apa itu bursa tanpa KYC? Kelebihan dan risikonya","description":"Pelajari cara kerja bursa tanpa KYC, beda DEX dan bursa terpusat tanpa verifikasi, serta risiko dana terkunci.","related":[["kyc","KYC (Know Your Customer)","KYC adalah proses verifikasi identitas yang wajib dilakukan bursa kripto dan lembaga keuangan, misalnya dengan KTP, foto wajah, dan data alamat, sebelum Anda bisa memakai layanan penuh."],["dex","DEX (decentralized exchange)","DEX adalah exchange kripto yang berjalan di smart contract, di mana Anda bertransaksi langsung dari dompet sendiri tanpa menyetor dana ke perusahaan perantara."],["withdrawal-fee","Biaya penarikan (withdrawal fee)","Biaya penarikan adalah biaya yang dipotong bursa saat Anda menarik kripto ke alamat lain atau menarik rupiah ke rekening bank, biasanya berupa jumlah tetap per transaksi yang bergantung pada koin dan jaringan."],["centralized-exchange","Centralized exchange (CEX)","Centralized exchange (CEX) adalah platform jual beli kripto yang dijalankan oleh sebuah perusahaan, yang menyimpan dana pengguna, mencocokkan order, dan biasanya mewajibkan verifikasi KYC."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"Bagaimana cara kerja KYC dan kepada siapa identitas diberikan?"},"coin":null,"tool":"/topics/no-kyc","cta":false},"fiat-on-ramp":{"slug":"fiat-on-ramp","cat":"regulation","en":"Fiat on-ramp","contentLocale":"id","term":"Fiat on-ramp","aka":["on-ramp","jalur fiat ke kripto","off-ramp"],"short":"Fiat on-ramp adalah layanan atau jalur untuk menukar uang biasa seperti rupiah menjadi aset kripto, misalnya lewat transfer bank, kartu, e-wallet, atau P2P di bursa.","body":["Kebalikannya disebut off-ramp, yaitu menukar kripto kembali ke rupiah dan menariknya ke rekening bank. Keduanya adalah pintu masuk dan keluar antara sistem keuangan tradisional dan dunia kripto.",["Jalur yang umum di Indonesia antara lain transfer bank atau virtual account ke bursa lokal berizin, pembayaran lewat e-wallet, kartu debit atau kredit, dan ",["P2P","p2p-trading"]," di bursa global. Setiap jalur punya biaya, kecepatan, dan batas berbeda. Pembelian lewat kartu biasanya cepat tetapi sering lebih mahal, sedangkan transfer bank lebih murah tetapi bisa butuh waktu."],["Bandingkan total biaya, bukan hanya biaya yang tertulis. Ada biaya transaksi, selisih kurs yang disembunyikan di harga, dan ",["biaya penarikan","withdrawal-fee"]," jika Anda memindahkan kripto ke bursa lain. Pastikan juga rekening atau kartu yang dipakai atas nama Anda sendiri, sesuai data ",["KYC","kyc"],"."]],"example":["Misalkan Anda ingin membeli ",["USDT","usdt"]," dengan Rp5.000.000. Jalur A memakai kartu dengan biaya 2% dan kurs Rp16.000, sehingga dana efektif Rp4.900.000 dan Anda menerima sekitar 306 USDT. Jalur B memakai transfer bank ke bursa lokal tanpa biaya setoran, tetapi kurs USDT di sana Rp16.150, sehingga Anda menerima sekitar 309 USDT. Meski jalur B memakai kurs lebih tinggi, hasilnya tetap lebih banyak karena tidak ada potongan 2%. Selalu hitung jumlah akhir yang Anda terima."],"mistakes":["Hanya melihat biaya tertulis tanpa memperhitungkan selisih kurs.","Memakai rekening atau kartu atas nama orang lain sehingga setoran ditolak.","Membeli kripto lewat pihak tidak resmi di media sosial demi kurs sedikit lebih murah."],"faq":[{"q":"Apa beda on-ramp dan off-ramp?","a":"On-ramp menukar uang fiat menjadi kripto, sedangkan off-ramp menukar kripto kembali ke uang fiat. Keduanya biasanya dilakukan lewat bursa atau penyedia pembayaran."},{"q":"Cara termurah membeli kripto dengan rupiah?","a":"Tidak ada satu jawaban untuk semua orang, karena biaya dan kurs berubah. Bandingkan jumlah akhir yang Anda terima dari beberapa jalur resmi dengan nominal yang sama."}],"title":"Apa itu fiat on-ramp? Cara beli kripto dengan rupiah","description":"Pelajari arti fiat on-ramp dan off-ramp, jalur membeli kripto dengan rupiah, serta cara membandingkan biaya dan kurs.","related":[["p2p-trading","P2P trading (jual beli P2P)","P2P trading adalah jual beli kripto langsung antarpengguna di platform bursa, di mana pembayaran rupiah dilakukan lewat transfer bank atau e-wallet dan kripto penjual ditahan sistem escrow."],["kyc","KYC (Know Your Customer)","KYC adalah proses verifikasi identitas yang wajib dilakukan bursa kripto dan lembaga keuangan, misalnya dengan KTP, foto wajah, dan data alamat, sebelum Anda bisa memakai layanan penuh."],["centralized-exchange","Centralized exchange (CEX)","Centralized exchange (CEX) adalah platform jual beli kripto yang dijalankan oleh sebuah perusahaan, yang menyimpan dana pengguna, mencocokkan order, dan biasanya mewajibkan verifikasi KYC."],["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"Deposit pertama: dari mana uang masuk dan ke mana perginya?"},"coin":null,"tool":null,"cta":true}});
